import React, { useEffect, useState } from "react";
import {
  MapContainer,
  TileLayer,
  CircleMarker,
  Popup,
  Circle,
  useMap,
} from "react-leaflet";
import "leaflet/dist/leaflet.css";

// Componente para ajustar la vista del mapa dinámicamente
const ChangeView = ({ coordenadas }) => {
  const map = useMap();

  useEffect(() => {
    if (coordenadas) {
      map.setView([coordenadas.lat, coordenadas.lng], 7); // Centra y ajusta el zoom en las coordenadas
    }
  }, [coordenadas, map]);

  return null;
};

const MapaMexico = ({ coordenadas, theme }) => {
  const [circleScale, setCircleScale] = useState(1); // Manejo del efecto de expansión del círculo
  const [opacity, setOpacity] = useState(0.6);

  // URL dinámica del TileLayer dependiendo del tema
  const tileLayerUrl =
    theme === "dark"
      ? "https://tiles.stadiamaps.com/tiles/alidade_smooth_dark/{z}/{x}/{y}{r}.png" // Tema oscuro
      : "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"; // Tema claro

  // Manejar el efecto de expansión de la onda sísmica
  useEffect(() => {
    if (!coordenadas) return;

    setCircleScale(1); // Reinicia la escala
    setOpacity(0.6); // Inicia con opacidad alta

    const interval = setInterval(() => {
      setCircleScale((prev) => prev + 0.05); // Expande el círculo gradualmente
      setOpacity((prev) => Math.max(prev - 0.01, 0)); // Reduce la opacidad gradualmente

      // Restablece cuando alcanza los límites (por estética)
      if (circleScale > 3 || opacity <= 0) {
        setCircleScale(1);
        setOpacity(0.6);
      }
    }, 50);

    return () => clearInterval(interval); // Limpia el intervalo al desmontar o cambiar coordenadas
  }, [coordenadas, circleScale, opacity]);

  return (
    <MapContainer
      center={[23.6345, -102.5528]} // Coordenadas iniciales de México
      zoom={5}
      style={{ height: "100vh", width: "100%" }}
    >
      {/* Fondo dinámico del mapa */}
      <TileLayer
        url={tileLayerUrl}
        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
        noWrap={true}
      />
      <ChangeView coordenadas={coordenadas} />

      {/* Marcadores y efecto dinámico (si hay coordenadas) */}
      {coordenadas && (
        <>
          <CircleMarker
            center={[coordenadas.lat, coordenadas.lng]}
            radius={10}
            color="red"
            fillColor="red"
            fillOpacity={0.7}
          >
            <Popup>
              <b>Ubicación del Sismo</b> <br />
              Lat: {coordenadas.lat}, Lng: {coordenadas.lng}
            </Popup>
          </CircleMarker>

          {/* Añade el efecto de onda sísmica */}
          <Circle
            center={[coordenadas.lat, coordenadas.lng]}
            radius={circleScale * 50000} // Multiplica para ajustar el tamaño
            color="red"
            fillColor="red"
            fillOpacity={opacity}
            stroke={false}
          />
        </>
      )}
    </MapContainer>
  );
};

export default MapaMexico;
